CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS roles (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role_id INT REFERENCES roles(id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS permissions (id SERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INT REFERENCES roles(id) ON DELETE CASCADE, permission_id INT REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, sort_order INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID REFERENCES categories(id), name TEXT NOT NULL, sku TEXT UNIQUE, price NUMERIC(12,2) NOT NULL CHECK(price>=0), tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK(tax_rate>=0), active BOOLEAN NOT NULL DEFAULT TRUE, kitchen_station TEXT NOT NULL DEFAULT 'kitchen', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dining_tables (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), table_number TEXT UNIQUE NOT NULL, capacity INT NOT NULL DEFAULT 2, status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','occupied','reserved','cleaning')));
CREATE TABLE IF NOT EXISTS customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT, phone TEXT UNIQUE, email TEXT, loyalty_points INT NOT NULL DEFAULT 0 CHECK(loyalty_points>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number BIGSERIAL UNIQUE, order_type TEXT NOT NULL CHECK(order_type IN ('counter','takeaway','dine_in')), table_id UUID REFERENCES dining_tables(id), customer_id UUID REFERENCES customers(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','held','placed','preparing','ready','served','completed','cancelled','refunded')), created_by UUID REFERENCES users(id), subtotal NUMERIC(12,2) NOT NULL DEFAULT 0, discount_total NUMERIC(12,2) NOT NULL DEFAULT 0, tax_total NUMERIC(12,2) NOT NULL DEFAULT 0, grand_total NUMERIC(12,2) NOT NULL DEFAULT 0, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), product_id UUID REFERENCES products(id), product_name TEXT NOT NULL, quantity NUMERIC(10,3) NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL, tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0, discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0, line_subtotal NUMERIC(12,2) NOT NULL, line_tax NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','preparing','ready','served','cancelled')));
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), method TEXT NOT NULL CHECK(method IN ('cash','upi','card','other')), amount NUMERIC(12,2) NOT NULL CHECK(amount>0), status TEXT NOT NULL DEFAULT 'captured' CHECK(status IN ('pending','captured','failed','refunded')), reference TEXT, received_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL UNIQUE REFERENCES orders(id), invoice_number TEXT UNIQUE NOT NULL, business_name TEXT NOT NULL, business_address TEXT, gstin TEXT, subtotal NUMERIC(12,2) NOT NULL, discount_total NUMERIC(12,2) NOT NULL, taxable_value NUMERIC(12,2) NOT NULL, tax_total NUMERIC(12,2) NOT NULL, grand_total NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','void','credited')), issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS kitchen_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), ticket_number BIGSERIAL UNIQUE, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','preparing','ready','served','cancelled')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reprint_count INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS kitchen_ticket_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES kitchen_tickets(id), order_item_id UUID NOT NULL REFERENCES order_items(id), quantity NUMERIC(10,3) NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','preparing','ready','served','cancelled')));
CREATE TABLE IF NOT EXISTS ingredients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, unit TEXT NOT NULL, stock_quantity NUMERIC(12,3) NOT NULL DEFAULT 0, reorder_level NUMERIC(12,3) NOT NULL DEFAULT 0, average_unit_cost NUMERIC(12,4) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS recipes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, ingredient_id UUID NOT NULL REFERENCES ingredients(id), quantity_required NUMERIC(12,3) NOT NULL CHECK(quantity_required>0), UNIQUE(product_id,ingredient_id));
CREATE TABLE IF NOT EXISTS stock_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ingredient_id UUID NOT NULL REFERENCES ingredients(id), quantity_delta NUMERIC(12,3) NOT NULL, reason TEXT NOT NULL, reference_type TEXT, reference_id UUID, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT, email TEXT, gstin TEXT, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID REFERENCES suppliers(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','received','cancelled')), total NUMERIC(12,2) NOT NULL DEFAULT 0, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), received_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS purchase_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, ingredient_id UUID NOT NULL REFERENCES ingredients(id), quantity NUMERIC(12,3) NOT NULL CHECK(quantity>0), unit_cost NUMERIC(12,4) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE IF NOT EXISTS loyalty_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES customers(id), order_id UUID REFERENCES orders(id), points_delta INT NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>0), expense_date DATE NOT NULL DEFAULT CURRENT_DATE, description TEXT, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), voided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, user_id UUID REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business_settings (id INT PRIMARY KEY DEFAULT 1 CHECK(id=1), business_name TEXT NOT NULL DEFAULT 'My Cafe', business_address TEXT, gstin TEXT, invoice_prefix TEXT NOT NULL DEFAULT 'INV', invoice_counter BIGINT NOT NULL DEFAULT 0, timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', loyalty_points_per_100 NUMERIC(6,2) NOT NULL DEFAULT 1, loyalty_point_value NUMERIC(6,2) NOT NULL DEFAULT 1);
INSERT INTO roles(name) VALUES ('owner'),('manager'),('cashier'),('kitchen') ON CONFLICT DO NOTHING;
INSERT INTO permissions(code,description) VALUES ('orders.manage','Create and manage orders'),('reports.read','View sales reports'),('menu.manage','Manage menu and prices'),('users.manage','Manage staff'),('refunds.manage','Issue refunds'),('kitchen.manage','Manage kitchen tickets'),('inventory.manage','Manage stock and purchases'),('expenses.manage','Manage expenses'),('profit.read','View profit reports'),('settings.manage','Manage business settings'),('customers.manage','Manage customers') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE (r.name='owner') OR (r.name='manager' AND p.code <> 'users.manage') OR (r.name='cashier' AND p.code IN ('orders.manage','customers.manage')) OR (r.name='kitchen' AND p.code='kitchen.manage') ON CONFLICT DO NOTHING;
INSERT INTO business_settings(id,business_name,business_address,gstin) VALUES(1,COALESCE(NULLIF(current_setting('app.business_name',true),''),'My Cafe'),NULLIF(current_setting('app.business_address',true),''),NULLIF(current_setting('app.gstin',true),'')) ON CONFLICT(id) DO NOTHING;
CREATE INDEX IF NOT EXISTS idx_orders_created_at ON orders(created_at);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_payments_order ON payments(order_id);
CREATE INDEX IF NOT EXISTS idx_stock_movements_ingredient ON stock_movements(ingredient_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_kitchen_status ON kitchen_tickets(status,created_at);
